package com.smartdairy.controller;
import com.smartdairy.entity.Distributor; import com.smartdairy.service.DistributorService; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException;
public class DistributorController extends HttpServlet{private final DistributorService service=new DistributorService(); protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{Distributor d=new Distributor();d.setName(r.getParameter("name"));d.setMobile(r.getParameter("mobile"));d.setShopName(r.getParameter("shop_name"));d.setAddress(r.getParameter("address"));d.setArea(r.getParameter("area"));d.setStatus(r.getParameter("status"));service.save(d);s.sendRedirect("distributor.jsp?success=true");}catch(Exception e){s.sendRedirect("distributor.jsp?error=true");}}}
